/**
 * Capability gate — L2 payments runtime block (Sprint 16).
 *
 * Every route that creates a PaymentIntent MUST call requireStudioL2Enabled()
 * as its FIRST DB operation. If the gate fails, return capabilityGateErrorResponse()
 * immediately — do not touch Stripe.
 *
 * Gate reads the studio_l2_payments_enabled RPC (S15) which returns the connected
 * account_id on success. The caller uses that account_id for transfer_data.destination.
 *
 * INVARIANT 7: This module is Stripe-agnostic — no Stripe SDK imports here.
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import { RPC, type StudioL2PaymentsEnabledResult } from '@/lib/payments/contracts'

// ---------------------------------------------------------------------------
// Error class
// ---------------------------------------------------------------------------

export class CapabilityGateError extends Error {
  constructor(
    public readonly reason: string,
    public readonly userMessage: string,
    public readonly httpStatus: number = 403,
  ) {
    super(`capability_gate: ${reason}`)
    this.name = 'CapabilityGateError'
  }
}

// ---------------------------------------------------------------------------
// Human-readable messages keyed by reason code
// ---------------------------------------------------------------------------

const REASON_MESSAGES: Record<string, string> = {
  no_connected_account: 'Set up in-studio payments before charging clients.',
  onboarding_pending: 'Stripe verification is still in progress.',
  onboarding_restricted: 'Stripe needs more documents to verify this account.',
  onboarding_rejected: 'This Stripe account cannot accept charges.',
  charges_disabled: 'Stripe has disabled charges on this account.',
}

// ---------------------------------------------------------------------------
// requireStudioL2Enabled
// ---------------------------------------------------------------------------

/**
 * Check L2 payments capability for a studio. Throws CapabilityGateError if disabled.
 *
 * Run as the FIRST DB call in any route that creates a PaymentIntent.
 * Returns the connected account_id on success — caller uses it for transfer_data.destination.
 *
 * Uses the service-role supabase client passed by the caller — capability gate
 * is an internal check and must not be RLS-filtered by the session user.
 */
export async function requireStudioL2Enabled(
  supabase: SupabaseClient,
  studioId: string,
): Promise<{ accountId: string }> {
  const { data, error } = await supabase.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
    p_studio_id: studioId,
  })

  if (error) throw error

  const result = data as StudioL2PaymentsEnabledResult

  if (!result.enabled) {
    const reason = result.reason ?? 'unknown_state'
    const message = REASON_MESSAGES[reason] ?? 'In-studio payments are not available right now.'
    throw new CapabilityGateError(reason, message, 403)
  }

  if (!result.account_id) {
    throw new CapabilityGateError(
      'account_id_missing',
      'Connected account record is incomplete.',
      500,
    )
  }

  return { accountId: result.account_id }
}

// ---------------------------------------------------------------------------
// capabilityGateErrorResponse
// ---------------------------------------------------------------------------

/**
 * Map a CapabilityGateError to a Next.js Response.
 * Use at the route boundary so each route handler doesn't duplicate the shape.
 */
export function capabilityGateErrorResponse(err: CapabilityGateError): Response {
  return Response.json(
    { error: 'capability_gate', reason: err.reason, message: err.userMessage },
    { status: err.httpStatus },
  )
}

/**
 * createSessionPaymentIntent — S16 core helper.
 *
 * Destination-charge flow for in-studio session settlement:
 *   1. Capability gate (L2 runtime block — CC from S15)
 *   2. Country alignment sanity check (CC18 — country immutable after account creation)
 *   3. Deposit pool SAGA step 1 — apply_deposit_to_session RPC (pending_apply row)
 *   4. Stripe PaymentIntent create with destination charge + application_fee_amount
 *   5. Mirror in stripe_charges table via stripe_charge_record RPC
 *
 * On PaymentIntent create failure: immediately roll back the deposit SAGA step 1
 * (rollback_deposit_application). Do NOT leave orphan pending_apply rows.
 *
 * INVARIANT 2: every Stripe call goes through withIdempotencyKey() + carries
 *              metadata.inkos_idempotency_key (enforced by the wrapper + explicit set).
 * INVARIANT 4: application_fee_amount is ALWAYS set (never undefined → studio gets nothing).
 * INVARIANT 7: This module is Stripe-only. No Dodo imports.
 * INVARIANT 8: Banker's rounding on commission splits (no systematic bias on .5 cents).
 *
 * Server-side only. Never import from client components.
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import type Stripe from 'stripe'
import { getStripe } from './client'
import { idempotencyKeyFor, withIdempotencyKey } from './idempotency'
import {
  requireStudioL2Enabled,
  CapabilityGateError,
} from '@/lib/payments/capability-gate'
import {
  RPC,
  type CentsAmount,
  type Currency,
  type ApplyDepositToSessionResult,
  type InkosIdempotencyKey,
} from '@/lib/payments/contracts'
import { logger } from '@/lib/logger'

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface CreateSessionPaymentIntentArgs {
  studioId: string
  bookingId: string
  projectId: string
  sessionId: string
  artistId: string
  clientId: string
  /** Stripe cus_xxx — must already exist; created during booking flow. */
  customerId: string
  /** Stripe pm_xxx — saved card on file. */
  paymentMethodId: string
  currency: Currency
  /** Session fee before deposit drawdown. */
  baseAmountCents: CentsAmount
  tipAmountCents: CentsAmount
  /** 0 if no drawdown from deposit pool. */
  depositDrawdownCents: CentsAmount
  /**
   * Artist's share of baseAmountCents expressed as a percentage (e.g. 70).
   * Studio receives (100 - commissionPct)% as the application_fee_amount.
   */
  commissionPct: number
  /**
   * Stripe acct_xxx for the artist's own Connect account.
   * null when the artist has not opted into direct payouts.
   * When null, the studio's connected account is the destination and payroll
   * handles artist disbursement out-of-band.
   */
  artistConnectedAccountId: string | null
  /** Stripe acct_xxx for the studio — always present. */
  studioConnectedAccountId: string
}

export interface CreateSessionPaymentIntentResult {
  paymentIntentId: string
  clientSecret: string | null
  status: Stripe.PaymentIntent.Status
  /** null when depositDrawdownCents === 0. */
  depositTransactionId: string | null
  /** base + tip - drawdown — what the client is actually charged. */
  amountChargedCents: CentsAmount
}

// ---------------------------------------------------------------------------
// Internal: commission split with banker's rounding (INVARIANT 8)
// ---------------------------------------------------------------------------

interface CommissionSplit {
  applicationFeeCents: CentsAmount // studio's share (goes to platform as application_fee)
  netArtistCents: CentsAmount      // artist's share
}

/**
 * Split baseAmountCents on commissionPct with banker's rounding (round half to even).
 *
 * Artist gets commissionPct%, studio gets (100 - commissionPct)%.
 * application_fee_amount = studio's cents (passed to Stripe as fee; stays on platform).
 * net_artist_cents = amount transferred to the destination (artist or studio account).
 */
function computeCommissionSplit(
  baseAmountCents: CentsAmount,
  commissionPct: number,
): CommissionSplit {
  // Studio share in raw fractional cents
  const studioPct = 100 - commissionPct
  const studioRaw = (baseAmountCents * studioPct) / 100

  // Banker's rounding: round half to even to avoid systematic bias.
  const floored = Math.floor(studioRaw)
  const fraction = studioRaw - floored
  let applicationFeeCents: number
  if (fraction < 0.5) {
    applicationFeeCents = floored
  } else if (fraction > 0.5) {
    applicationFeeCents = floored + 1
  } else {
    // Exactly 0.5 — round to nearest even
    applicationFeeCents = floored % 2 === 0 ? floored : floored + 1
  }

  const netArtistCents = baseAmountCents - applicationFeeCents

  return {
    applicationFeeCents: applicationFeeCents as CentsAmount,
    netArtistCents: netArtistCents as CentsAmount,
  }
}

// ---------------------------------------------------------------------------
// Internal: country alignment (CC18 — country immutable after account creation)
// ---------------------------------------------------------------------------

/**
 * Verify studios.country matches the studio's stripe_connected_accounts.country.
 *
 * A mismatch means the studio's country field drifted after account creation.
 * Since Stripe's country is immutable on the account, any drift is a data integrity
 * issue that must be resolved via support before charges can proceed.
 *
 * Throws CapabilityGateError (422) on drift or missing country.
 */
async function ensureCountryAligned(
  supabase: SupabaseClient,
  studioId: string,
): Promise<void> {
  // §S13.3 — types.ts regen pending; cast for studios.country read.
  const [studioResult, accountResult] = await Promise.all([
    supabase
      .from('studios')
      .select('country')
      .eq('id', studioId)
      .single(),
    supabase
      .from('stripe_connected_accounts')
      .select('country')
      .eq('studio_id', studioId)
      .eq('type', 'studio')
      .single(),
  ])

  if (studioResult.error) throw studioResult.error
  if (accountResult.error) throw accountResult.error

  const studioCountry = (studioResult.data as { country: string | null }).country
  const accountCountry = (accountResult.data as { country: string | null }).country

  if (!studioCountry) {
    throw new CapabilityGateError(
      'country_missing',
      'Studio country must be set before charging.',
      422,
    )
  }

  if (studioCountry !== accountCountry) {
    throw new CapabilityGateError(
      'country_drift',
      'Studio country no longer matches the Stripe account country. Contact support.',
      422,
    )
  }
}

// ---------------------------------------------------------------------------
// createSessionPaymentIntent
// ---------------------------------------------------------------------------

export async function createSessionPaymentIntent(
  supabase: SupabaseClient,
  args: CreateSessionPaymentIntentArgs,
): Promise<CreateSessionPaymentIntentResult> {
  const startedAt = Date.now()

  // 1. Capability gate — FIRST DB call, throws CapabilityGateError if disabled.
  await requireStudioL2Enabled(supabase, args.studioId)

  // 2. Country alignment sanity check (CC18 reinforced).
  await ensureCountryAligned(supabase, args.studioId)

  // 3. Deposit SAGA step 1: reserve drawdown BEFORE touching Stripe.
  let depositTransactionId: string | null = null
  if (args.depositDrawdownCents > 0) {
    const depositIdemKey = idempotencyKeyFor('deposit.apply_to_session', {
      session_id: args.sessionId,
      draw_cents: args.depositDrawdownCents,
    })

    const { data: applyData, error: applyErr } = await supabase.rpc(
      RPC.APPLY_DEPOSIT_TO_SESSION,
      {
        p_project_id: args.projectId,
        p_session_id: args.sessionId,
        p_draw_cents: args.depositDrawdownCents,
        p_idempotency_key: depositIdemKey,
      },
    )

    if (applyErr) throw applyErr

    const applyResult = applyData as ApplyDepositToSessionResult
    depositTransactionId = applyResult.transaction_id
  }

  // 4. Commission split (INVARIANT 8 — banker's rounding).
  const { applicationFeeCents, netArtistCents } = computeCommissionSplit(
    args.baseAmountCents,
    args.commissionPct,
  )

  // 5. Charged amount = base + tip - drawdown. Must be non-negative.
  const amountChargedCents = (
    args.baseAmountCents + args.tipAmountCents - args.depositDrawdownCents
  ) as CentsAmount

  if (amountChargedCents < 0) {
    // Roll back any pending deposit reservation before throwing.
    if (depositTransactionId) {
      const { error: rollbackErr } = await supabase.rpc(RPC.ROLLBACK_DEPOSIT_APPLICATION, {
        p_transaction_id: depositTransactionId,
        p_reason: 'payment_failed',
      })
      if (rollbackErr) {
        logger.error(
          { depositTransactionId, err: rollbackErr, studio_id: args.studioId },
          'CRITICAL: deposit rollback failed during negative-amount guard',
        )
      }
    }
    throw new Error(
      'createSessionPaymentIntent: amountChargedCents is negative — depositDrawdownCents exceeds base + tip',
    )
  }

  // 6. Destination account + effective application fee.
  //
  // When the artist has their own Connect account: transfer destination is the artist's
  // account; Stripe distributes the commission split in real-time.
  //
  // When the artist has NOT opted into direct payouts (null): destination is the studio's
  // account. Studio keeps 100% of base; payroll distributes the artist's share out-of-band.
  // We set effectiveApplicationFee to baseAmountCents so the entire base stays on the platform
  // (no automatic transfer to artist). Tips always flow to the destination account (studio or
  // artist) and are accounted for separately in commission_splits.
  const destinationAccount = args.artistConnectedAccountId ?? args.studioConnectedAccountId

  // INVARIANT 4: application_fee_amount is ALWAYS set (never undefined).
  const effectiveApplicationFee: CentsAmount =
    args.artistConnectedAccountId === null
      ? args.baseAmountCents   // studio keeps everything; payroll handles artist share
      : applicationFeeCents    // platform keeps studio's cut; artist gets net_artist_cents

  // 7. PaymentIntent idempotency key (INVARIANT 2).
  const piIdemKey: InkosIdempotencyKey = idempotencyKeyFor('payment_intent.create', {
    booking_id: args.bookingId,
    session_id: args.sessionId,
  })

  // 8. Stripe PaymentIntent — destination charge.
  const stripe = getStripe()
  let pi: Stripe.PaymentIntent

  try {
    pi = await withIdempotencyKey(piIdemKey, (key) =>
      stripe.paymentIntents.create(
        {
          amount: amountChargedCents,
          currency: args.currency,
          customer: args.customerId,
          payment_method: args.paymentMethodId,
          confirm: true,
          off_session: true,   // saved card; client not present at charge time
          // INVARIANT 4 — never omit application_fee_amount.
          application_fee_amount: effectiveApplicationFee,
          transfer_data: { destination: destinationAccount },
          on_behalf_of: destinationAccount,
          automatic_tax: { enabled: true },
          // INVARIANT 2 — inkos_idempotency_key in metadata for webhook reconciliation.
          metadata: {
            inkos_idempotency_key: key,
            inkos_studio_id: args.studioId,
            inkos_booking_id: args.bookingId,
            inkos_project_id: args.projectId,
            inkos_session_id: args.sessionId,
            inkos_artist_id: args.artistId,
            inkos_client_id: args.clientId,
            inkos_deposit_drawdown_cents: String(args.depositDrawdownCents),
            // Track D webhook handler uses this to call confirm_deposit_application.
            inkos_deposit_transaction_id: depositTransactionId ?? '',
          },
        },
        { idempotencyKey: key },
      ),
    )
  } catch (err) {
    // PaymentIntent creation failed — roll back deposit SAGA step 1 immediately.
    // Do NOT leave orphan pending_apply rows (reaper cron is last resort, not primary).
    if (depositTransactionId) {
      logger.warn(
        { depositTransactionId, studio_id: args.studioId, session_id: args.sessionId, err },
        'PI create failed — rolling back deposit SAGA step 1',
      )
      const { error: rollbackErr } = await supabase.rpc(RPC.ROLLBACK_DEPOSIT_APPLICATION, {
        p_transaction_id: depositTransactionId,
        p_reason: 'payment_failed',
      })
      if (rollbackErr) {
        logger.error(
          { depositTransactionId, err: rollbackErr, studio_id: args.studioId },
          'CRITICAL: deposit rollback failed after PI create error — orphan pending_apply row',
        )
      }
    }
    throw err
  }

  // 9. Mirror PI in stripe_charges (S13 RPC). Failure here is non-fatal — the PI
  // already succeeded on Stripe's side. Log the CRITICAL and let the reconciliation
  // cron catch the drift. Throwing here would leave a paid PI with no local record AND
  // an unresolved deposit SAGA, which is worse.
  const { error: chargeRecErr } = await supabase.rpc(RPC.STRIPE_CHARGE_RECORD, {
    p_studio_id: args.studioId,
    p_payment_intent_id: pi.id,
    p_status: pi.status,
    p_currency: pi.currency as Currency,
    p_amount_cents: pi.amount,
    p_tax_amount_cents: 0,           // updated via payment_intent.succeeded webhook (Stripe Tax)
    p_application_fee_cents: effectiveApplicationFee,
    p_net_artist_cents: netArtistCents,
    p_tip_amount_cents: args.tipAmountCents,
    p_booking_id: args.bookingId,
    p_project_id: args.projectId,
    p_session_id: args.sessionId,
    p_client_id: args.clientId,
    p_deposit_drawdown_cents: args.depositDrawdownCents,
    p_idempotency_key: piIdemKey,
    p_presentment_currency: null,
    p_presentment_amount_cents: null,
  })

  if (chargeRecErr) {
    logger.error(
      {
        pi_id: pi.id,
        studio_id: args.studioId,
        session_id: args.sessionId,
        err: chargeRecErr,
      },
      'CRITICAL: stripe_charge_record RPC failed after PI create — out of sync; reconciliation cron will catch',
    )
  }

  logger.info({
    studio_id: args.studioId,
    session_id: args.sessionId,
    payment_intent_id: pi.id,
    idempotency_key: piIdemKey,
    amount_cents: pi.amount,
    deposit_transaction_id: depositTransactionId,
    duration_ms: Date.now() - startedAt,
  }, 'session payment intent created')

  return {
    paymentIntentId: pi.id,
    clientSecret: pi.client_secret,
    status: pi.status,
    depositTransactionId,
    amountChargedCents,
  }
}

/**
 * POST /api/payments/charge
 *
 * Creates a destination-charge PaymentIntent for an in-studio session.
 *
 * Auth: owner | receptionist | artist (on this booking).
 * Rate limit: authedRatelimit (60 req/min per IP).
 *
 * Body:
 *   bookingId          string
 *   sessionId          string
 *   baseAmountCents    number (integer, minor units)
 *   tipAmountCents     number (integer, minor units, ≥ 0)
 *   depositDrawdownCents  number (integer, ≥ 0, optional — defaults to 0)
 *   paymentMethodId    string (pm_xxx — saved card on file)
 *
 * Capability gate: studio_l2_payments_enabled checked first; returns 403 if false.
 * Country check: studio.country must match stripe_connected_accounts.country; 422 if drift.
 * SAGA: apply_deposit_to_session called before PI create; rolled back on PI create failure.
 *
 * Success: 200 { payment_intent_id, status, amount_charged_cents, deposit_transaction_id }
 * Gate fail: 403 { error, reason, message }
 * Country drift: 422 { error, reason, message }
 * Stripe error: 502 { error }
 * Validation: 400 { error, issues }
 */

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { cents, type Currency } from '@/lib/payments/contracts'
import {
  CapabilityGateError,
  capabilityGateErrorResponse,
} from '@/lib/payments/capability-gate'
import { createSessionPaymentIntent } from '@/lib/stripe/charges'

// ---------------------------------------------------------------------------
// Input schema
// ---------------------------------------------------------------------------

const ChargeBodySchema = z.object({
  bookingId: z.string().uuid(),
  sessionId: z.string().uuid(),
  baseAmountCents: z.number().int().min(1),
  tipAmountCents: z.number().int().min(0).default(0),
  depositDrawdownCents: z.number().int().min(0).default(0),
  paymentMethodId: z.string().min(1).startsWith('pm_'),
})

type ChargeBody = z.infer<typeof ChargeBodySchema>

// ---------------------------------------------------------------------------
// Allowed roles
// ---------------------------------------------------------------------------

type StudioRole = 'owner' | 'artist' | 'receptionist' | 'admin' | 'guest_artist'

const ALLOWED_ROLES: StudioRole[] = ['owner', 'receptionist', 'artist', 'admin']

// ---------------------------------------------------------------------------
// Route handler
// ---------------------------------------------------------------------------

export async function POST(req: NextRequest) {
  const ip = getClientIp(req)
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return Response.json({ error: 'Rate limited' }, { status: 429 })
  }

  // Auth — session client (user-scoped RLS)
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Resolve studio membership + role
  const { data: member, error: memberErr } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (memberErr || !member) {
    return Response.json({ error: 'No active studio membership' }, { status: 403 })
  }

  const role = member.role as StudioRole
  if (!ALLOWED_ROLES.includes(role)) {
    return Response.json({ error: 'Insufficient role' }, { status: 403 })
  }

  // Parse + validate body
  let body: ChargeBody
  try {
    const raw = await req.json()
    body = ChargeBodySchema.parse(raw)
  } catch (err) {
    if (err instanceof z.ZodError) {
      return Response.json({ error: 'Validation failed', issues: err.issues }, { status: 400 })
    }
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const studioId = member.studio_id

  // Resolve booking context — confirm booking belongs to this studio
  // §S13.3 — types.ts regen pending; cast booking row.
  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select('id, client_id, artist_id, project_id, status')
    .eq('id', body.bookingId)
    .eq('studio_id', studioId)
    .single()

  if (bookingErr || !booking) {
    logger.warn({ bookingId: body.bookingId, studioId }, 'charge: booking not found')
    return Response.json({ error: 'Booking not found' }, { status: 404 })
  }

  const bookingRow = booking as {
    id: string
    client_id: string
    artist_id: string
    project_id: string | null
    status: string
  }

  // Resolve client's Stripe customer_id
  // §S13.3 — types.ts regen pending; cast client row.
  const { data: clientRow, error: clientErr } = await supabase
    .from('clients')
    .select('id, stripe_customer_id')
    .eq('id', bookingRow.client_id)
    .eq('studio_id', studioId)
    .single()

  if (clientErr || !clientRow) {
    logger.warn({ clientId: bookingRow.client_id, studioId }, 'charge: client not found')
    return Response.json({ error: 'Client not found' }, { status: 404 })
  }

  const client = clientRow as { id: string; stripe_customer_id: string | null }

  if (!client.stripe_customer_id) {
    return Response.json(
      { error: 'Client has no Stripe customer record. Complete the booking setup first.' },
      { status: 422 },
    )
  }

  // Resolve studio connected account
  const { data: studioAccount, error: studioAccErr } = await supabase
    .from('stripe_connected_accounts')
    .select('account_id')
    .eq('studio_id', studioId)
    .eq('type', 'studio')
    .single()

  if (studioAccErr || !studioAccount) {
    return Response.json(
      { error: 'Studio has no Stripe connected account. Complete Connect onboarding first.' },
      { status: 422 },
    )
  }

  const studioConnectedAccountId = (studioAccount as { account_id: string }).account_id

  // Resolve artist connected account (optional — artist may not have opted in)
  let artistConnectedAccountId: string | null = null
  if (bookingRow.artist_id) {
    const { data: artistAccount } = await supabase
      .from('stripe_connected_accounts')
      .select('account_id, onboarding_status')
      .eq('studio_id', studioId)
      .eq('type', 'artist')
      .eq('artist_id', bookingRow.artist_id)
      .single()

    if (artistAccount) {
      const acc = artistAccount as {
        account_id: string
        onboarding_status: string
      }
      // Only use artist account if fully active
      if (acc.onboarding_status === 'active') {
        artistConnectedAccountId = acc.account_id
      }
    }
  }

  // Resolve commission pct from team_members (falls back to default 70/30).
  // §S13.3 — types.ts regen pending; cast member row.
  let commissionPct = 70
  if (bookingRow.artist_id) {
    const { data: teamMember } = await supabase
      .from('team_members')
      .select('commission_pct')
      .eq('studio_id', studioId)
      .eq('profile_id', bookingRow.artist_id)
      .single()

    if (teamMember) {
      const tm = teamMember as { commission_pct: number | null }
      if (tm.commission_pct !== null) {
        commissionPct = tm.commission_pct
      }
    }
  }

  // Resolve currency from studio (default usd)
  const { data: studioRow } = await supabase
    .from('studios')
    .select('default_currency')
    .eq('id', studioId)
    .single()

  const currency: Currency =
    (studioRow as { default_currency: string | null } | null)?.default_currency as Currency ?? 'usd'

  // Resolve projectId — fall back to booking's project_id (may be null for walk-ins)
  const projectId = bookingRow.project_id

  if (!projectId && body.depositDrawdownCents > 0) {
    return Response.json(
      { error: 'Cannot draw deposit on a booking without a project.' },
      { status: 422 },
    )
  }

  // Service-role client for SAGA RPC writes (bypasses RLS — these are internal ledger ops)
  const serviceSupabase = createServiceRoleClient()

  // createSessionPaymentIntent wraps: capability gate → country check → deposit SAGA → Stripe PI → mirror
  let result: Awaited<ReturnType<typeof createSessionPaymentIntent>>
  try {
    result = await createSessionPaymentIntent(serviceSupabase, {
      studioId,
      bookingId: body.bookingId,
      projectId: projectId ?? body.bookingId, // walk-in: use bookingId as synthetic projectId
      sessionId: body.sessionId,
      artistId: bookingRow.artist_id,
      clientId: bookingRow.client_id,
      customerId: client.stripe_customer_id,
      paymentMethodId: body.paymentMethodId,
      currency,
      baseAmountCents: cents(body.baseAmountCents),
      tipAmountCents: cents(body.tipAmountCents),
      depositDrawdownCents: cents(body.depositDrawdownCents),
      commissionPct,
      artistConnectedAccountId,
      studioConnectedAccountId,
    })
  } catch (err) {
    if (err instanceof CapabilityGateError) {
      return capabilityGateErrorResponse(err)
    }

    // Stripe errors — sanitize; never leak internal Stripe error details to client.
    const message =
      err instanceof Error
        ? err.message.slice(0, 200)
        : 'An unexpected error occurred while creating the charge.'

    logger.error(
      {
        studio_id: studioId,
        session_id: body.sessionId,
        booking_id: body.bookingId,
        err,
      },
      'charge: unexpected error',
    )

    return Response.json({ error: message }, { status: 502 })
  }

  // Audit log — non-fatal (logAuditAction catches its own errors)
  await logAuditAction(
    user.id,
    'session_charge_created',
    { type: 'payment_intent', id: result.paymentIntentId },
    {
      session_id: body.sessionId,
      booking_id: body.bookingId,
      amount_charged_cents: result.amountChargedCents,
      deposit_transaction_id: result.depositTransactionId,
      status: result.status,
    },
    studioId,
  )

  return Response.json({
    payment_intent_id: result.paymentIntentId,
    status: result.status,
    amount_charged_cents: result.amountChargedCents,
    deposit_transaction_id: result.depositTransactionId,
  })
}

