// automatic_tax: not available on PaymentIntents in the pinned SDK version
// (2026-04-22.dahlia). Tax amounts are read from the charge object on
// payment_intent.succeeded and updated in stripe_charges via webhook.
// INVARIANT 2 — inkos_idempotency_key in metadata for webhook reconciliation.

input.content:
/**
 * POST /api/payments/charge
 *
 * Creates a destination-charge PaymentIntent for an in-studio session.
 *
 * Auth: owner | receptionist | artist (on this booking).
 * Rate limit: authedRatelimit (60 req/min per IP).
 *
 * Body:
 *   bookingId          string
 *   sessionId          string
 *   baseAmountCents    number (integer, minor units)
 *   tipAmountCents     number (integer, minor units, ≥ 0)
 *   depositDrawdownCents  number (integer, ≥ 0, optional — defaults to 0)
 *   paymentMethodId    string (pm_xxx — saved card on file)
 *
 * Capability gate: studio_l2_payments_enabled checked first; returns 403 if false.
 * Country check: studio.country must match stripe_connected_accounts.country; 422 if drift.
 * SAGA: apply_deposit_to_session called before PI create; rolled back on PI create failure.
 *
 * Success: 200 { payment_intent_id, status, amount_charged_cents, deposit_transaction_id }
 * Gate fail: 403 { error, reason, message }
 * Country drift: 422 { error, reason, message }
 * Stripe error: 502 { error }
 * Validation: 400 { error, issues }
 */

import type { NextRequest } from 'next/server'
import type { SupabaseClient } from '@supabase/supabase-js'
import { z } from 'zod'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { cents, type Currency } from '@/lib/payments/contracts'
import {
  CapabilityGateError,
  capabilityGateErrorResponse,
} from '@/lib/payments/capability-gate'
import { createSessionPaymentIntent } from '@/lib/stripe/charges'

// ---------------------------------------------------------------------------
// Input schema
// ---------------------------------------------------------------------------

const ChargeBodySchema = z.object({
  bookingId: z.string().uuid(),
  sessionId: z.string().uuid(),
  baseAmountCents: z.number().int().min(1),
  tipAmountCents: z.number().int().min(0).default(0),
  depositDrawdownCents: z.number().int().min(0).default(0),
  paymentMethodId: z.string().min(1).startsWith('pm_'),
})

type ChargeBody = z.infer<typeof ChargeBodySchema>

// ---------------------------------------------------------------------------
// Allowed roles
// ---------------------------------------------------------------------------

type StudioRole = 'owner' | 'artist' | 'receptionist' | 'admin' | 'guest_artist'

const ALLOWED_ROLES: StudioRole[] = ['owner', 'receptionist', 'artist', 'admin']

// ---------------------------------------------------------------------------
// §S13.3 helpers — untyped reads for S16 tables not yet in types.ts
//
// stripe_connected_accounts, team_members: created in S13 migrations but
// types.ts has not been regenerated (Track C owns pnpm db:types after S16 migration).
// Use raw SupabaseClient (no Database generic) for these queries.
// ---------------------------------------------------------------------------

interface ClientRow {
  id: string
  stripe_customer_id: string | null
}

interface StudioConnectedAccountRow {
  account_id: string
}

interface ArtistConnectedAccountRow {
  account_id: string
  onboarding_status: string
}

interface TeamMemberRow {
  commission_pct: number | null
}

interface StudioDefaultCurrencyRow {
  default_currency: string | null
}

/**
 * Fetch client with stripe_customer_id.
 * §S13.3 — cast through unknown to bypass types.ts column gap.
 */
async function fetchClientRow(
  db: SupabaseClient,
  clientId: string,
  studioId: string,
): Promise<ClientRow | null> {
  const { data, error } = await db
    .from('clients')
    .select('id, stripe_customer_id')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()
  if (error || !data) return null
  // §S13.3 — stripe_customer_id not yet in generated types; cast through unknown.
  return data as unknown as ClientRow
}

/**
 * Fetch studio connected account.
 * §S13.3 — stripe_connected_accounts not yet in generated types.
 */
async function fetchStudioConnectedAccount(
  db: SupabaseClient,
  studioId: string,
): Promise<StudioConnectedAccountRow | null> {
  const { data, error } = await db
    .from('stripe_connected_accounts')
    .select('account_id')
    .eq('studio_id', studioId)
    .eq('type', 'studio')
    .single()
  if (error || !data) return null
  return data as unknown as StudioConnectedAccountRow
}

/**
 * Fetch artist connected account (returns null if not found or not active).
 * §S13.3 — stripe_connected_accounts not yet in generated types.
 */
async function fetchArtistConnectedAccount(
  db: SupabaseClient,
  studioId: string,
  artistId: string,
): Promise<ArtistConnectedAccountRow | null> {
  const { data } = await db
    .from('stripe_connected_accounts')
    .select('account_id, onboarding_status')
    .eq('studio_id', studioId)
    .eq('type', 'artist')
    .eq('artist_id', artistId)
    .single()
  if (!data) return null
  return data as unknown as ArtistConnectedAccountRow
}

/**
 * Fetch artist commission pct from team_members.
 * §S13.3 — commission_pct column not yet in generated types.
 */
async function fetchArtistCommissionPct(
  db: SupabaseClient,
  studioId: string,
  artistId: string,
): Promise<number | null> {
  const { data } = await db
    .from('team_members')
    .select('commission_pct')
    .eq('studio_id', studioId)
    .eq('profile_id', artistId)
    .single()
  if (!data) return null
  return (data as unknown as TeamMemberRow).commission_pct
}

/**
 * Fetch studio default_currency.
 */
async function fetchStudioDefaultCurrency(
  db: SupabaseClient,
  studioId: string,
): Promise<string | null> {
  const { data } = await db
    .from('studios')
    .select('default_currency')
    .eq('id', studioId)
    .single()
  if (!data) return null
  return (data as unknown as StudioDefaultCurrencyRow).default_currency
}

// ---------------------------------------------------------------------------
// Route handler
// ---------------------------------------------------------------------------

export async function POST(req: NextRequest) {
  const ip = getClientIp(req)
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return Response.json({ error: 'Rate limited' }, { status: 429 })
  }

  // Auth — session client (user-scoped RLS)
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Resolve studio membership + role
  const { data: member, error: memberErr } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (memberErr || !member) {
    return Response.json({ error: 'No active studio membership' }, { status: 403 })
  }

  const role = member.role as StudioRole
  if (!ALLOWED_ROLES.includes(role)) {
    return Response.json({ error: 'Insufficient role' }, { status: 403 })
  }

  // Parse + validate body
  let body: ChargeBody
  try {
    const raw = await req.json()
    body = ChargeBodySchema.parse(raw)
  } catch (err) {
    if (err instanceof z.ZodError) {
      return Response.json({ error: 'Validation failed', issues: err.issues }, { status: 400 })
    }
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const studioId = member.studio_id

  // Confirm booking belongs to this studio (typed query — bookings IS in types.ts)
  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select('id, client_id, artist_id, project_id, status')
    .eq('id', body.bookingId)
    .eq('studio_id', studioId)
    .single()

  if (bookingErr || !booking) {
    logger.warn({ bookingId: body.bookingId, studioId }, 'charge: booking not found')
    return Response.json({ error: 'Booking not found' }, { status: 404 })
  }

  // §S13.3 — bookings row may have columns not in types.ts; cast through unknown.
  const bookingRow = booking as unknown as {
    id: string
    client_id: string
    artist_id: string
    project_id: string | null
    status: string
  }

  // Service-role client (untyped SupabaseClient base) for S16-schema table reads
  // and SAGA RPC writes (bypasses RLS — these are internal ledger operations).
  const serviceSupabase: SupabaseClient = createServiceRoleClient()

  // Resolve client row + stripe_customer_id
  const clientRow = await fetchClientRow(serviceSupabase, bookingRow.client_id, studioId)
  if (!clientRow) {
    logger.warn({ clientId: bookingRow.client_id, studioId }, 'charge: client not found')
    return Response.json({ error: 'Client not found' }, { status: 404 })
  }
  if (!clientRow.stripe_customer_id) {
    return Response.json(
      { error: 'Client has no Stripe customer record. Complete the booking setup first.' },
      { status: 422 },
    )
  }

  // Resolve studio connected account
  const studioAccount = await fetchStudioConnectedAccount(serviceSupabase, studioId)
  if (!studioAccount) {
    return Response.json(
      { error: 'Studio has no Stripe connected account. Complete Connect onboarding first.' },
      { status: 422 },
    )
  }
  const studioConnectedAccountId = studioAccount.account_id

  // Resolve artist connected account (optional — artist may not have opted into direct payouts)
  let artistConnectedAccountId: string | null = null
  if (bookingRow.artist_id) {
    const artistAccount = await fetchArtistConnectedAccount(
      serviceSupabase,
      studioId,
      bookingRow.artist_id,
    )
    if (artistAccount?.onboarding_status === 'active') {
      artistConnectedAccountId = artistAccount.account_id
    }
  }

  // Resolve commission pct (falls back to default 70/30 if not set on team_members row)
  let commissionPct = 70
  if (bookingRow.artist_id) {
    const pct = await fetchArtistCommissionPct(serviceSupabase, studioId, bookingRow.artist_id)
    if (pct !== null) {
      commissionPct = pct
    }
  }

  // Resolve currency from studio (default usd)
  const defaultCurrency = await fetchStudioDefaultCurrency(serviceSupabase, studioId)
  const currency: Currency = (defaultCurrency as Currency | null) ?? 'usd'

  // Resolve projectId — deposit draw requires a project; walk-ins have null
  const projectId = bookingRow.project_id
  if (!projectId && body.depositDrawdownCents > 0) {
    return Response.json(
      { error: 'Cannot draw deposit on a booking without a project.' },
      { status: 422 },
    )
  }

  // createSessionPaymentIntent: capability gate → country check → deposit SAGA → Stripe PI → mirror
  let result: Awaited<ReturnType<typeof createSessionPaymentIntent>>
  try {
    result = await createSessionPaymentIntent(serviceSupabase, {
      studioId,
      bookingId: body.bookingId,
      // walk-in fallback: use bookingId as synthetic projectId for RPC call
      projectId: projectId ?? body.bookingId,
      sessionId: body.sessionId,
      artistId: bookingRow.artist_id,
      clientId: bookingRow.client_id,
      customerId: clientRow.stripe_customer_id,
      paymentMethodId: body.paymentMethodId,
      currency,
      baseAmountCents: cents(body.baseAmountCents),
      tipAmountCents: cents(body.tipAmountCents),
      depositDrawdownCents: cents(body.depositDrawdownCents),
      commissionPct,
      artistConnectedAccountId,
      studioConnectedAccountId,
    })
  } catch (err) {
    if (err instanceof CapabilityGateError) {
      return capabilityGateErrorResponse(err)
    }

    // Stripe errors — log full error server-side; return sanitized message to client.
    logger.error(
      {
        studio_id: studioId,
        session_id: body.sessionId,
        booking_id: body.bookingId,
        err,
      },
      'charge: PaymentIntent create error',
    )

    const message =
      err instanceof Error
        ? err.message.slice(0, 200)
        : 'An unexpected error occurred while creating the charge.'

    return Response.json({ error: message }, { status: 502 })
  }

  // Audit log — non-fatal (logAuditAction catches its own errors internally)
  await logAuditAction(
    user.id,
    'session_charge_created',
    { type: 'payment_intent', id: result.paymentIntentId },
    {
      session_id: body.sessionId,
      booking_id: body.bookingId,
      amount_charged_cents: result.amountChargedCents,
      deposit_transaction_id: result.depositTransactionId,
      status: result.status,
    },
    studioId,
  )

  return Response.json({
    payment_intent_id: result.paymentIntentId,
    status: result.status,
    amount_charged_cents: result.amountChargedCents,
    deposit_transaction_id: result.depositTransactionId,
  })
}
